from pathlib import Path
import json,sqlite3,pandas as pd,numpy as np
from model import paired,build_panel,stress
from common import *
ROOT=Path(__file__).parent;OUT=ROOT/'outputs'
def main():
 facts=json.loads((ROOT/'data/companyfacts_selected.json').read_text());panel,lineage,exceptions=build_panel(facts);panel.to_csv(OUT/'ttm_panel.csv',index=False);lineage.to_csv(OUT/'source_lineage.csv',index=False);dump(OUT/'excluded_periods.json',exceptions)
 latest=panel[panel.end=='2026-09-30'].copy();assert len(latest)==3
 cells=pd.DataFrame(json.loads((ROOT/'data/original_filing_cells.json').read_text()));checks=[]
 for _,r in cells.iterrows():
  candidates=lineage[(lineage.symbol==r.symbol)&(lineage.metric==r.metric)&(lineage.start==r.start)&(lineage.end==r.end)&(lineage.accession==r.accession)];assert len(candidates)>0;assert all(abs(candidates.value-r.value)<1e-6);checks.append(dict(symbol=r.symbol,metric=r.metric,start=r.start,end=r.end,source_value=r.value,difference=0,accession=r.accession))
 pd.DataFrame(checks).to_csv(OUT/'original_filing_reconciliation.csv',index=False)
 con=sqlite3.connect(':memory:');lineage.to_sql('lineage',con,index=False);q=(ROOT/'reconcile.sql').read_text();sql=pd.read_sql_query(q,con);sql.to_csv(OUT/'sql_ttm.csv',index=False)
 for _,r in sql.iterrows():v=panel[(panel.symbol==r.symbol)&(panel.end==r.ttm_end)][r.metric].item();assert abs(v-r.ttm_value)<1e-5
 grid=[]
 for _,row in latest.iterrows():
  for shock in [0,.05,.1,.2]:
   for growth in [0,.1,.2,.3]:
    for retained in [0,10e9,20e9]:
     v=stress(row.cfo,row.capex,shock,growth,0,retained);grid.append(dict(symbol=row.symbol,cfo_decline_pct=shock*100,capex_growth_pct=growth*100,retained_target=retained,**v))
 pd.DataFrame(grid).to_csv(OUT/'scenario_grid.csv',index=False)
 ytd=[]
 for symbol in ['MSFT','GOOGL','META']:
  start='2026-07-01' if symbol=='MSFT' else '2026-01-01';pair=paired(facts,symbol,start,'2026-09-30');ytd.append(dict(symbol=symbol,start=start,end='2026-09-30',cfo=pair['cfo']['val'],capex=pair['capex']['val'],cash_after_capex=pair['cfo']['val']-pair['capex']['val'],accession=pair['cfo']['accn']))
 pd.DataFrame(ytd).to_csv(OUT/'current_fiscal_ytd.csv',index=False)
 fig,ax=plt.subplots(figsize=(10,4.8));x=np.arange(3);ax.bar(x-.2,latest.cfo/1e9,.4,color='#87c5ff',label='Operating cash flow');ax.bar(x+.2,latest.capex/1e9,.4,color='#f5cb8a',label='Cash purchases of property / equipment');ax.set_xticks(x,latest.symbol);ax.set_ylabel('USD billions, trailing twelve months');ax.legend(loc='upper center',bbox_to_anchor=(.5,1.18),ncol=2,frameon=False);ax.set_title('The same twelve months, different cash-flow pressure',loc='left',pad=43);savefig(OUT,'cash-coverage',fig)
 fig,ax=plt.subplots(figsize=(10,4.8));colors=['#87c5ff','#f5cb8a','#b7a5eb']
 for (symbol,g),color in zip(panel.groupby('symbol'),colors):ax.plot(pd.to_datetime(g.end),g.capex_to_cfo*100,marker='.',label=symbol,color=color)
 ax.axhline(100,ls='--',color='#9fb7cc');ax.set_ylabel('Cash property purchases / operating cash (%)');ax.set_title('Spending absorbs a changing share of operating cash',loc='left',pad=38);ax.legend(loc='upper center',bbox_to_anchor=(.5,1.14),ncol=3,frameon=False);savefig(OUT,'cash-intensity',fig)
 google=latest[latest.symbol=='GOOGL'].iloc[0];g_ytd=next(x for x in ytd if x['symbol']=='GOOGL');finding=f"Alphabet's January-September 2026 cash purchases of property and equipment exceed operating cash flow by ${-g_ytd['cash_after_capex']/1e9:.3f} billion. On a common trailing-year basis, operating cash remaining after those purchases is still ${google.cash_after_capex/1e9:.3f} billion. The measurement window changes the funding story."
 limits='These are consolidated company cash flows, not isolated AI or cloud-segment spending. Cash property purchases omit noncash finance-lease additions and do not measure total investment commitments. Cash after capex is before acquisitions, financing and shareholder distributions and is not a liquidity or covenant test. Fiscal YTD spans differ across companies and are never ranked as equal windows. Historical facts are original-current disclosure selections under a 120-day filing window, with prior YTD comparatives from the same current filing; they are not a real-time investment backtest. Amazon is excluded from the paired PPE comparison because its productive-asset cash tag has a different scope. No AI return, stock valuation or financing recommendation is inferred.'
 dump(OUT/'summary.json',dict(period_end='2026-09-30',filing_cutoff='2026-10-30',finding=finding,limitations=limits,issuers=latest.to_dict('records'),original_filing_cells=len(checks),historical_rows=len(panel),excluded_periods=len(exceptions),amazon_scope='PaymentsToAcquireProductiveAssets differs from the primary PPE tag; not silently substituted.'))
 latest[['symbol','period_start','end','cfo','capex','cash_after_capex','capex_to_cfo']].to_csv(OUT/'latest_comparable_ttm.csv',index=False)
 body='<section class="section"><h2>The headline needs a cash-flow window.</h2><p>'+finding+'</p><div class="note">Observed: SEC cash-flow facts through September 30, filed by October 30, 2026. Scenario: future CFO changes, property spending growth, other uses and retained-cash targets are assumptions, not company guidance.</div>'+figure(OUT,'cash-coverage','Consolidated cash flows for October 2025-September 2026. The two bars share the same 12-month window; cash purchases are a cash-flow definition, not total AI investment.')+table(pd.DataFrame({'Company':latest.symbol,'Operating cash ($bn)':latest.cfo/1e9,'Cash PPE ($bn)':latest.capex/1e9,'After PPE ($bn)':latest.cash_after_capex/1e9,'PPE/CFO (%)':latest.capex_to_cfo*100}))+'<h2>What a finance analyst should ask</h2><p>Before deciding that a business can sustain an investment plan, test how much operating cash can fall while a specified amount is retained after cash property purchases and other assumed uses. The workbench solves that boundary directly. It does not rank stocks or estimate returns on AI assets.</p>'+figure(OUT,'cash-intensity','Reconciled trailing-year ratios from paired source facts. Excluded periods are disclosed in the downloadable audit; revised comparative data and differing disclosures limit historical comparability.')+'<h2>Why fiscal YTD is kept separate</h2><p>Microsoft’s current fiscal YTD is July-September; Alphabet and Meta report January-September. Those windows are shown with their explicit start dates, not used as a like-for-like ranking.</p>'+table(pd.DataFrame(ytd).assign(cfo=lambda x:x.cfo/1e9,capex=lambda x:x.capex/1e9,cash_after_capex=lambda x:x.cash_after_capex/1e9).drop(columns='accession').rename(columns={'cfo':'Operating cash ($bn)','capex':'Cash PPE ($bn)','cash_after_capex':'After PPE ($bn)'}))+'<h2>Source audit and scope</h2><p>'+str(len(checks))+' selected numeric cells reconcile to the original current-quarter and annual SEC filing contexts, scales and values. The full TTM lineage records every annual/current/prior-YTD contribution and accession. Independent SQL reproduces every retained TTM total. Missing period pairs remain excluded rather than filled.</p><p>Amazon was reviewed but is kept out of the paired PPE chart: its current cash-flow tag is PaymentsToAcquireProductiveAssets. Substituting a broader asset definition would create a misleading comparison.</p><p><a href="workbench.html">Stress the cash-retention boundary</a></p><details><summary>Method and limits</summary><p>For interim periods, TTM = prior fiscal annual + current YTD − prior-year YTD. Both YTD terms come from the same accession. Annual terms and current periods are selected from filings within 120 days of period end and no later than the cutoff. The scenario uses CFO × (1 − shock) − capex × (1 + growth) − assumed other uses. Its cash-retention target is an annual flow, not a balance-sheet minimum.</p><p>'+limits+'</p></details><h2>Download the evidence</h2><p><a href="latest_comparable_ttm.csv">Latest comparison</a> · <a href="source_lineage.csv">Every source contribution</a> · <a href="original_filing_reconciliation.csv">Original filing checks</a> · <a href="sql_ttm.csv">SQL totals</a> · <a href="scenario_grid.csv">Scenario grid</a> · <a href="excluded_periods.json">Excluded periods</a></p></section>'
 page(ROOT,'report.html','Can operating cash keep pace with capital spending?',finding,body)
 options=''.join('<option value="'+x['symbol']+'">'+x['symbol']+'</option>' for x in latest.to_dict('records'));controls=[('shock','Operating cash decline (%)',0),('growth','Cash property-spending growth (%)',10),('uses','Other assumed annual cash uses ($bn)',0),('target','Retained annual operating cash target ($bn)',20)]
 form='<section class="section"><p class="note">Observed base: common trailing year ending September 2026. Every changed input below is hypothetical. This is an annual cash-flow screen, not a liquidity forecast.</p><form id="scenario"><div class="formgrid"><label for="issuer">Company<select id="issuer">'+options+'</select></label>'+''.join(f'<label for="{i}">{label}<input id="{i}" type="number" value="{v}" step="any" required></label>' for i,label,v in controls)+'</div><button type="submit">Recalculate the boundary</button></form><div id="results" aria-live="polite" class="results"></div><button id="download" type="button">Download scenario JSON</button><details><summary>Interpret this screen</summary><p>'+limits+'</p><p>A negative maximum-growth boundary means spending must fall under the specified cash target. A negative CFO-decline boundary means CFO must rise instead. Neither number is a forecast or management target. A target above all available CFO is infeasible even if property spending were zero.</p></details></section>'
 page(ROOT,'workbench.html','Where does the capital-spending plan stop fitting?','Challenge the operating-cash, spending and retained-cash assumptions.',form,(OUT/'calculator.js').read_text(),dict(issuers=latest.to_dict('records')))
 (ROOT/'docs/executive_memo.md').write_text('# Capital spending and cash retention\n\n'+finding+'\n\n## Decision use\nUse the common TTM comparison to identify which investment plans need a retained-cash challenge. Replace hypothetical other uses and targets with a company-approved forecast before drawing a funding conclusion. The fiscal-YTD comparison shows why an apparent deficit and a positive trailing-year residual can coexist.\n\n## Scope and limitations\n'+limits+'\n');print(finding)
if __name__=='__main__':main()
